# Instead of SAT with all those clauses, let's try a smarter approach:
# Use known constructions. The McGee graph is a 3-regular graph with 24 vertices, girth 7.
# For 19 vertices, girth 7, 3-colorable with 26 edges, let's try a direct construction
# or use a greedy/random search.

import random
from itertools import combinations

def has_short_cycle(adj, u, v, max_len):
    """Check if adding edge (u,v) creates a cycle of length <= max_len"""
    # BFS from u to v without using edge (u,v)
    from collections import deque
    dist = {u: 0}
    queue = deque([u])
    while queue:
        node = queue.popleft()
        if dist[node] >= max_len - 1:
            continue
        for nb in adj[node]:
            if nb == v:
                return True  # found path of length dist[node]+1 <= max_len-1, so cycle <= max_len
            if nb not in dist:
                dist[nb] = dist[node] + 1
                queue.append(nb)
    return False

def is_3_colorable(adj, n):
    """Check 3-colorability via backtracking"""
    color = [-1] * n
    def bt(v):
        if v == n:
            return True
        for c in range(3):
            if all(color[u] != c for u in adj[v]):
                color[v] = c
                if bt(v+1):
                    return True
                color[v] = -1
        return False
    return bt(0)

def try_build_graph(n, min_edges, min_girth, seed):
    random.seed(seed)
    adj = [set() for _ in range(n)]
    edges = []

    all_pairs = [(u,v) for u in range(n) for v in range(u+1,n)]
    random.shuffle(all_pairs)

    for u, v in all_pairs:
        if len(edges) >= min_edges:
            break
        # Check girth constraint
        if not has_short_cycle(adj, u, v, min_girth):
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u,v))

    return edges, adj

