# Let me try a more sophisticated approach - simulated annealing / local search
# to try to push beyond 23 edges

import random
from collections import deque

def compute_girth(adj, n):
    """Compute girth using BFS from each vertex"""
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = deque([(start, -1)])  # (node, parent)
        while queue:
            u, par = queue.popleft()
            for v in adj[u]:
                if v == par:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append((v, u))
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

def compute_girth_fast(adj, n):
    """Faster girth computation"""
    min_cycle = float('inf')
    for start in range(n):
        # BFS
        dist = {}
        dist[start] = 0
        queue = deque([start])
        prev = {start: -1}
        while queue and min_cycle > 2:
            u = queue.popleft()
            if dist[u] >= min_cycle // 2:
                continue
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    prev[v] = u
                    queue.append(v)
                elif prev[u] != v:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

# Start with best known 23-edge graph and try to improve
# Use edge swap: remove an edge, add two new edges

def local_search_girth7(n, max_iter=100000, seed=42):
    random.seed(seed)

    # Build initial valid graph
    adj = [set() for _ in range(n)]
    edges = set()

    pairs = [(u,v) for u in range(n) for v in range(u+1,n)]
    random.shuffle(pairs)

    for u, v in pairs:
        # Check if adding creates short cycle
        ok = True
        # BFS from u to v
        dist = {u: 0}
        queue = deque([u])
        found = False
        while queue and not found:
            node = queue.popleft()
            if dist[node] >= 5:  # max_len-1 = 6-1 = 5... wait girth 7 means no cycle <= 6
                continue
            for nb in adj[node]:
                if nb == v:
                    found = True
                    break
                if nb not in dist:
                    dist[nb] = dist[node] + 1
                    queue.append(nb)
        if not found:
            adj[u].add(v)
            adj[v].add(u)
            edges.add((u,v))

    best_edges = len(edges)
    print(f"Initial: {best_edges} edges")

    # Now try to improve by swapping edges
    for iteration in range(max_iter):
        if not edges:
            break

        # Try adding a random non-edge
        all_non_edges = [(u,v) for u in range(n) for v in range(u+1,n) if (u,v) not in edges]
        if not all_non_edges:
            break

        u, v = random.choice(all_non_edges)

        # Check if we can add it directly
        dist = {u: 0}
        queue = deque([u])
        found = False
        while queue and not found:
            node = queue.popleft()
            if dist[node] >= 5:
                continue
            for nb in adj[node]:
                if nb == v:
                    found = True
                    break
                if nb not in dist:
                    dist[nb] = dist[node] + 1
                    queue.append(nb)

        if not found:
            adj[u].add(v)
            adj[v].add(u)
            edges.add((u,v))
            if len(edges) > best_edges:
                best_edges = len(edges)
                print(f"Iter {iteration}: {best_edges} edges")
        else:
            # Try removing an edge to make room
            # Remove a random edge from the short path
            edge_list = list(edges)
            e_remove = random.choice(edge_list)
            a, b = e_remove
            adj[a].discard(b)
            adj[b].discard(a)
            edges.discard(e_remove)

            # Now try adding (u,v)
            dist = {u: 0}
            queue = deque([u])
            found = False
            while queue and not found:
                node = queue.popleft()
                if dist[node] >= 5:
                    continue
                for nb in adj[node]:
                    if nb == v:
                        found = True
                        break
                    if nb not in dist:
                        dist[nb] = dist[node] + 1
                        queue.append(nb)

            if not found:
                adj[u].add(v)
                adj[v].add(u)
                edges.add((u,v))
            else:
                # Restore
                adj[a].add(b)
                adj[b].add(a)
                edges.add(e_remove)

    return edges, adj

edges, adj = local_search_girth7(19, max_iter=50000, seed=42)
